$setup=$cleanup+"insert into auth.users(id,email)values('$studentA','epic6-race-a@example.invalid'),('$studentB','epic6-race-b@example.invalid'),('$teacherA','epic6-race-teacher-a@example.invalid'),('$teacherB','epic6-race-teacher-b@example.invalid'),('$admin','epic6-race-admin@example.invalid');insert into public.user_roles(user_id,role)values('$teacherA','teacher'),('$teacherB','teacher'),('$admin','admin');insert into public.teacher_profiles(user_id,public_slug,bio,teaching_status,is_public,teaching_modes,trial_price_twd,default_meeting_provider,default_meeting_url)values('$teacherA','epic6-race-teacher-a','Race A','active',true,array['online']::public.teaching_mode[],500,'manual_google_meet','https://meet.google.com/abc-defg-hij'),('$teacherB','epic6-race-teacher-b','Race B','active',true,array['online']::public.teaching_mode[],500,'manual_zoom','https://zoom.us/j/123456789');insert into public.student_teacher_relationships(id,student_user_id,teacher_user_id,relationship_status,preferred_mode)values('$relationshipA','$studentA','$teacherA','active','online'),('$relationshipB','$studentB','$teacherA','active','online'),('$relationshipATeacherB','$studentA','$teacherB','active','online');insert into public.teacher_scheduling_settings(teacher_user_id,timezone,minimum_booking_notice_minutes,booking_horizon_days,slot_interval_minutes)values('$teacherA','UTC',0,90,10),('$teacherB','UTC',0,90,10);insert into public.teacher_availability_rules(teacher_user_id,weekday,local_start_time,local_end_time,timezone,effective_from,effective_until,created_by)select '$teacherA'::uuid,extract(dow from current_date+14)::smallint,'08:00'::time,'23:30'::time,'UTC',current_date,current_date+90,'$teacherA'::uuid union all select '$teacherB'::uuid,extract(dow from current_date+14)::smallint,'08:00'::time,'23:30'::time,'UTC',current_date,current_date+90,'$teacherB'::uuid;insert into public.entitlements(id,beneficiary_user_id,teacher_scope_user_id,entitlement_type,status,starts_at,expires_at,product_name_snapshot,booking_mode_eligibility,lesson_duration_minutes)values('$flexA','$studentA','$teacherA','lesson_package','active',now()-interval '1 day',now()+interval '6 months','Race Flex A','both',50),('$flexB','$studentB','$teacherA','lesson_package','active',now()-interval '1 day',now()+interval '6 months','Race Flex B','both',50),('$fixedA','$studentA','$teacherA','lesson_package','active',now()-interval '1 day',now()+interval '6 months','Race Fixed A','fixed',50),('$finalA','$studentA','$teacherA','lesson_package','active',now()-interval '1 day',now()+interval '6 months','Race Final A','both',50),('$releaseA','$studentA','$teacherA','lesson_package','active',now()-interval '1 day',now()+interval '6 months','Race Release A','both',50),('$consumeA','$studentA','$teacherA','lesson_package','active',now()-interval '1 day',now()+interval '6 months','Race Consume A','both',50),('$cancelConsumeA','$studentA','$teacherA','lesson_package','active',now()-interval '1 day',now()+interval '6 months','Race Cancel Consume A','both',50);insert into public.lesson_credit_ledger(entitlement_id,beneficiary_user_id,entry_type,available_delta,operation_key,reason_code)values('$flexA','$studentA','allocation',20,'epic6-race-flex-a','fixture'),('$flexB','$studentB','allocation',20,'epic6-race-flex-b','fixture'),('$fixedA','$studentA','allocation',20,'epic6-race-fixed-a','fixture'),('$finalA','$studentA','allocation',1,'epic6-race-final-a','fixture'),('$releaseA','$studentA','allocation',1,'epic6-race-release-a','fixture'),('$consumeA','$studentA','allocation',1,'epic6-race-consume-a','fixture'),('$cancelConsumeA','$studentA','allocation',1,'epic6-race-cancel-consume-a','fixture');"
function Slot([int]$Hour){"((current_date+14)::timestamp+interval '$Hour hours') at time zone 'UTC'"}
function Make-Series([string]$Student,[string]$Relationship,[int]$Hour,[string]$Entitlement,[string]$Reason){"select public.create_recurring_lesson_series('$Student','$teacherA','$Relationship','$Entitlement',extract(dow from current_date+14)::smallint,'$($Hour.ToString('00')):00'::time,'UTC',50::smallint,current_date+14,current_date+14,'$Reason');"}
function Db-Uuid([string]$Sql){$r=Invoke-Db $Sql;Must $r 'UUID query';$m=[regex]::Matches($r.Output,'(?i)[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}');if($m.Count-eq 0){throw "No UUID in: $($r.Output)"};$m[$m.Count-1].Value}

