  Inspect $race;$wins=@($race|Where-Object{$_.ExitCode-eq 0}).Count;if($wins-ne 1-or @($race|Where-Object{$_.ExitCode-ne 0-and$_.Output-notmatch'ERROR:\s+(42501|P0001)'}).Count-ne 0){$stats.Partial++;throw "K consume completion expected one consistent winner: $($race.Output-join' | ')"};Count "select count(*) from public.lesson_credit_ledger where reservation_id='$reservationK' and entry_type='consumption'" 1 'K one consumption';Count "select count(*) from public.bookings b join public.lessons l on l.id=b.lesson_id join public.lesson_credit_reservations r on r.id=b.credit_reservation_id where b.id='$bookingK' and b.status='completed' and l.status='completed' and r.status='consumed'" 1 'K completed final state';Count "select count(*) from public.entitlements where id='$consumeA' and status='exhausted'" 1 'K exhausted entitlement';'K [PASS] Epic 5 consume vs Epic 6 completion same reservation'

