  Inspect $race;One-Winner $race 'L release vs cancellation consume';Count "select count(*) from public.lesson_credit_ledger where reservation_id='$reservationL' and entry_type='consumption' and reason_code='admin_cancellation_consumed'" 1 'L one semantic consumption';Count "select count(*) from public.lesson_credit_ledger where reservation_id='$reservationL' and entry_type='release'" 0 'L no release';Count "select count(*) from public.bookings b join public.lesson_credit_reservations r on r.id=b.credit_reservation_id where b.id='$bookingL' and b.status='cancelled' and b.cancellation_credit_outcome='consumed' and r.status='consumed'" 1 'L consistent cancellation state';Count "select count(*) from public.entitlements where id='$cancelConsumeA' and status='exhausted'" 1 'L exhausted entitlement';'L [PASS] Epic 5 release vs Epic 6 cancellation-consume'

